R({id:'ui-speech', stage:'board', variants:[{key:'A', label:'Speech bubble (live showSpeechBubble)', play:ctx=>{ showSpeechBubble(ctx.board.mine[1], 'For the river!'); return ctx.wait(1800); }}]});
