R({id:'meta-nest-hatch', stage:'screen', note:'The hatch overlay with the game’s classes, played in the same order as hatchRevealVfx (rock ×3, shine, flash, card).', variants:[{key:'A', label:'Rock, cracks, beams, flash, the card (now)', play:async ctx=>{
  const ov = overlay(`<div class="hatch-flash"></div><div class="hatch-stage"><div class="hatch-rays"></div><div class="hatch-beams">${Array.from({length:12}, (_, k)=> `<i style="--a:${k*30}deg; --d:${(k%3)*0.08}s"></i>`).join('')}</div><div class="hatch-egg"><span class="he-ico">🥚</span></div></div>`, 'hatch-ov hatch-rare', 5200);
  const egg = ov.querySelector('.hatch-egg');
  for(let i = 0; i < 3; i++){ egg.classList.remove('rock'); void egg.offsetWidth; egg.classList.add('rock', 'crack' + (i + 1)); egg.style.setProperty('--rock', (6 + i*5) + 'deg'); ctx.sound('trigger'); await ctx.wait(i < 2 ? 650 : 600); }
  ov.classList.add('is-shining'); egg.classList.remove('rock'); egg.classList.add('shine'); await ctx.wait(1100); ov.classList.add('is-flash'); await ctx.wait(250);
  egg.classList.add('burst'); ov.classList.add('is-open'); ctx.sound('unlockChime'); await ctx.wait(250); ov.classList.remove('is-flash'); await ctx.wait(1200); ov.remove(); }}]});
