const wl = ctx=> ctx.ui.results;
R({id:'res-victory', stage:'ui', variants:[{key:'A', label:'Rays and the spring entrance (now)', play:ctx=>{ const c = wl(ctx), ic = c.querySelector('.pass-ico'); ctx.sound('win');
  ctx.gsap.fromTo(c, {opacity:0, scale:.55, y:26, rotate:-3}, {opacity:1, scale:1, y:0, rotate:0, duration:.62, ease:'back.out(1.8)', clearProps:'all'}); if(ic) ctx.gsap.fromTo(ic, {scale:0, rotate:-20}, {scale:1, rotate:0, duration:.5, delay:.32, ease:'back.out(3.2)'}); return ctx.wait(1800); }}]});
const fallen = ctx=>{ const c = wl(ctx); c.classList.remove('is-glory'); c.classList.add('is-fallen'); const r = c.querySelector('.wl-rays-clip'); if(r) r.outerHTML = `<div class="wl-dusk">${Array.from({length:10}, (_, k)=> `<i style="left:${(k*29+7)%100}%; animation-delay:-${(k*0.9).toFixed(1)}s; animation-duration:${(7 + (k*1.7)%5).toFixed(1)}s"></i>`).join('')}</div>`; c.querySelector('.pass-ico').textContent = '💀'; c.querySelector('.wl-title').textContent = 'Defeat'; return c; };
R({id:'res-defeat', stage:'ui', variants:[{key:'A', label:'Dusk and falling ash (now)', play:ctx=>{ fallen(ctx); return ctx.wait(2200); }}]});
const drawCard = ctx=>{ const c = wl(ctx); c.classList.remove('is-glory'); const r = c.querySelector('.wl-rays-clip'); if(r) r.remove(); c.querySelector('.pass-ico').textContent = '🤝'; c.querySelector('.wl-title').textContent = 'Draw!'; return c; };
